sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.menuOpen = false;

  c.toggleMenu = function() {
    c.menuOpen = !c.menuOpen;
  };

  c.closeMenu = function() {
    c.menuOpen = false;
  };
};

sp_widget.css:
.cah-header {
  width: 100%;
  background: #ffffff;
  border-bottom: 1px solid #e5e7eb;
  font-family: Arial, sans-serif;
  position: relative;
  z-index: 1000;
}

.header-container {
  max-width: 1200px;
  min-height: 82px;
  margin: auto;
  padding: 0 30px;

  display: flex;
  align-items: center;
}

/* Brand */

.brand {
  display: flex;
  align-items: center;
  text-decoration: none;
  color: #111827;
}

.brand-icon {
  width: 44px;
  height: 44px;

  display: flex;
  align-items: center;
  justify-content: center;

  background: #2563eb;
  color: #ffffff;

  border-radius: 10px;

  font-size: 21px;
  font-weight: bold;

  margin-right: 12px;
}

.brand-name {
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 2px;
}

.brand-subtitle {
  margin-top: 3px;
  color: #6b7280;
  font-size: 12px;
}

/* Desktop Navigation */

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 32px;

  margin-left: auto;
}

.desktop-nav a {
  color: #374151;
  font-size: 14px;
  text-decoration: none;
  white-space: nowrap;
}

.desktop-nav a:hover {
  color: #2563eb;
}

.login-btn {
  margin-left: 32px;

  padding: 10px 22px;

  background: #2563eb;
  color: #ffffff;

  border-radius: 7px;

  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}

/* Mobile button - hidden on desktop */

.mobile-menu-btn {
  display: none;

  margin-left: auto;

  width: 44px;
  height: 44px;

  border: none;
  background: #f3f4f6;

  border-radius: 8px;

  color: #111827;
  font-size: 20px;
}

/* Mobile menu */

.mobile-nav {
  display: none;
}


/* =========================
   MOBILE
========================= */

@media (max-width: 768px) {

  .header-container {
    min-height: 72px;
    padding: 0 18px;
  }

  .desktop-nav,
  .login-btn {
    display: none;
  }

  .mobile-menu-btn {
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .mobile-nav {
    display: flex;
    flex-direction: column;

    width: 100%;
    padding: 10px 18px 20px;

    background: #ffffff;
    border-top: 1px solid #e5e7eb;
  }

  .mobile-nav a {
    padding: 14px 5px;

    color: #374151;
    font-size: 15px;
    text-decoration: none;

    border-bottom: 1px solid #f3f4f6;
  }

  .mobile-login {
    margin-top: 12px;

    padding: 12px 15px !important;

    background: #2563eb;
    color: #ffffff !important;

    text-align: center;
    border-radius: 7px;
    border-bottom: none !important;
  }

  .brand-icon {
    width: 40px;
    height: 40px;
    font-size: 18px;
  }

  .brand-name {
    font-size: 15px;
    letter-spacing: 1.5px;
  }

  .brand-subtitle {
    font-size: 11px;
  }

}
